/*
 * hstrans.c - HS/Link, transmit side
 *
 */

#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <io.h>
#include <conio.h>
#include <fcntl.h>
#include <share.h>
#include <dos.h>

#include "hdktext.h"
#include "hspriv.h"
#include <hdk.h>

/* -------------------------------------------------------------- */

/* prototypes for private local procedures */

static int pascal send_header_block(char *path);

static int pascal send_data_block(block_number num);

static int pascal send_verify_block(block_number start);

static void pascal reduce_window(void);

static void pascal send_dle_char(uchar c);

static void pascal send_dle_block(uchar *data,
                                  int size);


/* -------------------------------------------------------------------- */

void pascal reduce_window(void)
{
        clock_t timer;
        long delay;

        if (WS.Option.MaxWind > 2)
        {
                --WS.Option.MaxWind;
                display_settings();
        }

        if (WS.tx_cps)
                delay = (1000L * SEND_FILE.BlockSize) / WS.tx_cps;
        else
                delay = PRIVATE.block_time;

        timer = SET_TIMER(delay+1000L);
        while (!TIMER_UP(timer) && !WS.cancel_link)
        {
                ComIdle(601);
                service_receive();
        }
}

/* -------------------------------------------------------------------- */

/* transmit each outgoing file (received files are processed in
   the background, during ACK waits).
   must be called repeatedly with each pathname until a 0 return
   value is seen.  non-0 return value indicates a transmit is in
   progress and that additional transmit_file calls are required to
   complete the transmit. */

int pascal transmit_file(char *path)
{
        switch (PRIVATE.transmit_context)
        {
        case 0:
        case 1:
               if (WS.cancel_link)
                       return 0;

                WS.send_current = 0;
                WS.send_skip = 0;
                WS.transmit_errors = 0;
                WS.resend_count = 0;
                WS.Comstat.TransmitHolds = 0;
                LAST_SENT = 0;
                PRIVATE.last_txack = 0;
                PRIVATE.ptx_pending = 0;
                PRIVATE.timeout_count = 0;
                PRIVATE.verify_requested = 0;
                PRIVATE.next_verify = 1;
                PRIVATE.ack_timeout = ACK_TIMEOUT + PRIVATE.block_time;

                PRIVATE.verify_active = WS.Option.ResumeVerify;
                PRIVATE.logcode = 'h';
                mem_clear(&PRIVATE.send_pack,sizeof(PRIVATE.send_pack));

                /* open file, set fd and blocks and send file header to remote */

                if (send_header_block(path))
                        return PRIVATE.transmit_context = 0;

                /* determine maximum contents in txque to allow another
                   block to be enqueued.  also take effective speed into
                   account for lower speeds to improve response time */
                {
                        long temp = ComWriteMax() -
                                    BLOCK_SIZE(SEND_FILE,1) - 100L;
                        PRIVATE.max_pending = temp > 10? temp:10;
                }

#ifdef DEBUG
                printf("max_pending(1)=%d\n",PRIVATE.max_pending);
#endif
                if (PRIVATE.max_pending > WS.Option.EffSpeed/16)
                        PRIVATE.max_pending = WS.Option.EffSpeed/16;
#ifdef DEBUG
                printf("max_pending(2)=%d\n",PRIVATE.max_pending);
#endif

                WS.tx_start = bios_clock();
                PRIVATE.idle_timeout = SET_TIMER( PRIVATE.ack_timeout );

                if (!PRIVATE.verify_active)
                        file_bargraph(0,SEND_FILE.size,0);

                return PRIVATE.transmit_context = 2;

        case 2:
                /* send each block in the file;
                   reposition at the receiver's request */

                /* link has been cancelled? */
                if (WS.cancel_link)
                {
                        PRIVATE.logcode = 'e';
                        ESEND(TX_ABORTED);
                        return PRIVATE.transmit_context = 3;
                }

                /* carrier lost? */
                if (ComCarrierLost())
                {
                        PRIVATE.logcode = 'l';
                        return PRIVATE.transmit_context = 3;
                }

                /* remote requested to skip file? */
                if (PRIVATE.skip_file_pending)
                {
                        PRIVATE.skip_file_pending = 0;
                        PRIVATE.logcode = 'e';
                        ESEND(TX_SKIPREM,LAST_SENT);
                        return PRIVATE.transmit_context = 3;
                }

                /* remote requested to restart file? */
                if (PRIVATE.reset_file_pending)
                {
                        PRIVATE.reset_file_pending = 0;
                        bclose(&PRIVATE.send_fd);
                        transmit_message(PACK_CLOSE_FILE, NULL, 0);
                        ESEND(TX_RESTARTING,LAST_SENT);
                        return PRIVATE.transmit_context = 1;
                }

                /*
                 * process a ready_pending message if we are expecting
                 * a file handshake
                 *
                 */
                if (PRIVATE.ready_pending == READY_SEND_FILE)
                {
                        PRIVATE.ready_pending = 0;
                        PRIVATE.verify_active = 0;
                }
                else

                if (PRIVATE.ready_pending == READY_SEND_VERIFY)
                {
                        PRIVATE.ready_pending = 0;
                        PRIVATE.next_verify = 1;
                        PRIVATE.verify_requested = 1;
                }

                /*
                 * process any pending ACK messages, setting last_txack to
                 * the highest block number that has been ACKed 
                 */

                if (PRIVATE.ack_pending)
                {
                        long unacked_total;
                        PRIVATE.last_txack = PRIVATE.ack_pending;
                        PRIVATE.ack_pending = 0;

                        unacked_total = (long) BLOCK_BYTES(SEND_FILE,LAST_SENT);
                        WS.send_current = (long) BLOCK_BYTES(SEND_FILE,PRIVATE.last_txack);
                        WS.tx_cps = calculate_cps(WS.tx_start,WS.send_current-WS.send_skip);
                        PRIVATE.curwindow = LAST_SENT - PRIVATE.last_txack;

                        /* update 'w:window' status display */
                        limit_errors(-201);
                        if (WS.Option.Debug != 2)
                        {
                                PSEND(TX_TXBLOCK,
                                        (int) LAST_SENT,
                                        unacked_total,
                                        (int) PRIVATE.curwindow,
                                        (int) WS.tx_cps);
                        }

                        file_bargraph(WS.send_current,SEND_FILE.size,WS.tx_cps);

#ifdef DEBUG
                        if (WS.Option.Debug)
                                printf("<USE ACK %u>\r\n", (int) PRIVATE.last_txack);
#endif

                        PRIVATE.idle_timeout = SET_TIMER( PRIVATE.ack_timeout );
                        PRIVATE.timeout_count = 0;
                        PRIVATE.verify_active = 0;
                }


                /* determine how many blocks have not been ack'd yet */

                PRIVATE.curwindow = (LAST_SENT - PRIVATE.last_txack) + 1;

                /*
                 * Check for nak messages from the receiver.  If we get one,
                 * resend the offending block, but continue where we were
                 * before the nak came in.  This takes advantage of the fact
                 * that the receiver can receive blocks out of order and
                 * will issue additional nak messages for any other bad
                 * blocks.
                 * This is the secret of full-streaming-error-recovery,
                 * which (as far as I know) is not used by any other
                 * communication protocol on the PC.
                 */

                if (PRIVATE.nak_pending)
                {
                        ++WS.resend_count;
                        report_tx_error(TX_RESENDING,PRIVATE.nak_pending);
                        limit_errors(201);

                        if (WS.resend_count > PRIVATE.nak_pending)
                                reduce_window();

                        if (send_data_block(PRIVATE.nak_pending))
                                PRIVATE.reset_file_pending = 1;

                        PRIVATE.nak_pending = 0;

                        /* if we're at eof, try the final block again
                           to prevent an ack timeout */
                        if (LAST_SENT == SEND_FILE.blocks)
                                --LAST_SENT;

                        PRIVATE.timeout_count = 0;
                        PRIVATE.idle_timeout = SET_TIMER( PRIVATE.ack_timeout );
                        PRIVATE.verify_active = 0;
                }

                /* in worst case error conditions we seek back to some
                   other position in the file */

                if (PRIVATE.seek_pending)
                {
                        if (PRIVATE.verify_active)
                        {
                                ESEND(TX_TXRECOVERY,
                                        PRIVATE.seek_pending);
                        }
                        else {
                                report_tx_error(
                                        PRIVATE.seek_pending<LAST_SENT?
                                                TX_SEEKBACK:
                                                TX_SEEKFORWARD,
                                        PRIVATE.seek_pending);

                                /* reduce WS.Option.MaxWind to prevent future errors
                                   in case of flow control failure */
                                if (PRIVATE.seek_pending < LAST_SENT)
                                        reduce_window();
                        }

                        LAST_SENT = PRIVATE.seek_pending-1;
                        PRIVATE.last_txack = LAST_SENT-1;
                        PRIVATE.seek_pending = 0;
                        if (PRIVATE.verify_active)
                        {
                                WS.tx_start = bios_clock();
                                if (LAST_SENT)
                                {
                                        WS.send_skip = BLOCK_BYTES(SEND_FILE,LAST_SENT);
                                        WS.send_skip_total += WS.send_skip;
                                }
                        }
                        PRIVATE.verify_active = 0;
                }

                /*
                 * send verify blocks if we are in recovery mode and
                 * no blocks have been acked by the receiver
                 * receiver responds by sending
                 *
                 */

                if (PRIVATE.verify_active && PRIVATE.next_verify)
                {
                        if (PRIVATE.verify_requested)
                        {
                                if (send_verify_block(PRIVATE.next_verify))
                                        PRIVATE.next_verify = 0;
                                else
                                        PRIVATE.next_verify += MAX_VERIFY_COUNT;
                        }
                        PRIVATE.timeout_count = 0L;
                        PRIVATE.idle_timeout = SET_TIMER( PRIVATE.ack_timeout+VERIFY_TIMEOUT );
                }


                /*
                 * send the next block if there are more to send and
                 * there are not too many pending (un-acked) blocks
                 */

                if ( (LAST_SENT < SEND_FILE.blocks) &&
                     (WS.Option.DisableAck || (PRIVATE.curwindow <= WS.Option.MaxWind)) &&
                     (!PRIVATE.verify_active) &&
                     (ComWritePending() < PRIVATE.max_pending) )
                {
                        long current;
                        ++LAST_SENT;
                        if (WS.Option.DisableAck)
                                WS.tx_cps = calculate_cps(WS.tx_start,
                                        BLOCK_BYTES(SEND_FILE,LAST_SENT-1)-
                                        ComWritePending()-
                                        WS.send_skip);

                        current = BLOCK_BYTES(SEND_FILE,LAST_SENT);
                        limit_errors(-202);
                        PSEND(TX_TXBLOCK,
                                (int) LAST_SENT,
                                (long) current,
                                (int) PRIVATE.curwindow,
                                (int) WS.tx_cps);

                        if (WS.Option.DisableAck)
                        {
                                WS.send_current = current;
                                file_bargraph(WS.send_current,SEND_FILE.size,WS.tx_cps);
                        }

                        if (send_data_block(LAST_SENT>0? LAST_SENT:1))
                                PRIVATE.reset_file_pending = 1;

                        PRIVATE.idle_timeout = SET_TIMER( PRIVATE.ack_timeout );
                }
                else

                /* we can't send a block right now- check for possible
                   timeout conditions */
                {
                        int tx_pending;

                        /* reset timeout if data is still going out */
                        tx_pending = ComWritePending();
                        if (tx_pending != PRIVATE.ptx_pending)
                        {
                                PRIVATE.ptx_pending = tx_pending;
                                PRIVATE.idle_timeout = SET_TIMER( PRIVATE.ack_timeout );

                                /* send a partial chat block if possible */
                                send_chat_block();
                        }

                        /* see if we have been idle long enough */
                        if (TIMER_UP(PRIVATE.idle_timeout))
                        {
                                PRIVATE.idle_timeout = SET_TIMER( PRIVATE.ack_timeout );
                                PRIVATE.verify_active = 0;

                                if (tx_pending)
                                {
                                        limit_errors(202);
                                        ESEND(TX_FLOWRELEASE);
                                        ComReportStatus(1101);
                                        newline();
					ComCancelXoff();
                                }

                                if (++PRIVATE.timeout_count > MAX_TIMEOUT)
                                {
                                        if (!ComGetCts())
                                        {
                                                limit_errors(203);
                                                ESEND(TX_CTSLOCK);
                                                set_cancel_link(CANCEL_FLOW_LOCKUP);
                                        } else {
                                                limit_errors(204);
                                                ESEND(TX_EXCESSTO);
                                                ComReportStatus(1101);
                                                set_cancel_link(CANCEL_REMOTE_TIMEOUT);
                                        }

                                }
                                else {
                                        if (LAST_SENT == 0)
                                                LAST_SENT = 1;

                                        report_tx_error(TX_ACKTO,LAST_SENT);
                                        ComReportStatus(1101);
                                        limit_errors(205);

                                        /* compensate for report_tx_error action */
                                        --WS.transmit_errors;

                                        if (WS.resend_count > PRIVATE.last_txack)
                                                LAST_SENT = PRIVATE.last_txack;
                                        else
                                                --LAST_SENT;
                                        ++WS.resend_count;
                                }

                                ++WS.transmit_errors;
                        }
                }

		/*
		 * continue sending mode until all blocks have been sent,
		 * acked, and no more acks or naks are pending 
		 */

                return PRIVATE.transmit_context =
                        ((LAST_SENT  < SEND_FILE.blocks) ||
                         (PRIVATE.last_txack < SEND_FILE.blocks) ||
                         PRIVATE.ack_pending || PRIVATE.nak_pending) ? 2:3;

        case 3:

                /* calculate transfer rate */

                if (WS.Option.DisableAck)
                        WS.tx_cps = calculate_cps(WS.tx_start,SEND_FILE.size-WS.send_skip);

                file_bargraph(WS.send_current,SEND_FILE.size,WS.tx_cps);
                if (PRIVATE.logcode == 'h')
                {
                        ESEND(TX_TXFILEOK,      (int)SEND_FILE.batch,
                                                (int)WS.tx_cps,
                                                sectomin(TIMER_SECS(WS.tx_start)));
                        ++WS.files_sent;
                }

                /* close file, tell receiver to mark EOF, transaction finished */

                transmit_message(PACK_CLOSE_FILE, NULL, 0);
                bclose(&PRIVATE.send_fd);

                /* make an entry in DSZLOG */

                update_status_log(
                                PRIVATE.logcode,
                                WS.send_current,
                                WS.Option.EffSpeed,
                                WS.tx_cps,
                                WS.resend_count,
                                WS.Comstat.TransmitHolds,
                                FINAL_BLOCK_SIZE(SEND_FILE),
                                                /* conversion loss warning ok */
                                path);

                WS.send_skip_total += (SEND_FILE.size - WS.send_current);
                WS.send_total += SEND_FILE.size;
                WS.send_current = 0;

                return PRIVATE.transmit_context = 0;
        }

        return PRIVATE.transmit_context = 0;
}


/* -------------------------------------------------------------------- */

/* open file, set send_fd and blocks, send file header block to remote.
   returns non-0 if file cannot be sent */

int pascal send_header_block(char *path)
{
        mem_clear(&SEND_FILE,sizeof(SEND_FILE));
        SEND_FILE.batch = ++PRIVATE.txbatch;
        SEND_FILE.BlockSize = WS.Option.BlockSize;

        ComIoStart(41);
        bopen(&PRIVATE.send_fd, path, WS.buffer_sizes, SEND_FILE.BlockSize, O_RDONLY | SH_DENYNONE);
        if (PRIVATE.send_fd.berr)
        {
                ComIoEnd(42);
                ESEND(TX_CANTOPTX, path);
                return 1;
	}

        /* determine file size, timestamp, and number of blocks to send */

        getftime(PRIVATE.send_fd.handle, &SEND_FILE.time);

        SEND_FILE.size = filelength(PRIVATE.send_fd.handle);
        ComIoEnd(43);

        SEND_FILE.blocks = (SEND_FILE.size / (long)SEND_FILE.BlockSize);
        if ((SEND_FILE.size % (long)SEND_FILE.BlockSize) != 0L)
                SEND_FILE.blocks++;

        /* remove pathname drive:\path, and copy to destination */

        strncpy(SEND_FILE.name, name_only(path), sizeof(SEND_FILE.name));

        /* finish the packet and transmit it */

        transmit_message(PACK_OPEN_FILE,(uchar *)&SEND_FILE,sizeof(SEND_FILE));

        select_send();
        display_file_banner(TX_TRANSMITTING,path,SEND_FILE.blocks,SEND_FILE.size);

        return 0;
}


/* -------------------------------------------------------------------- */

/* send a block from the specified file */

int pascal send_data_block(block_number num)
{
        int n;
        uchar *s;
        long rsize;
        unsigned counts[256];
        int send_seq;
        int send_map;

        /* locate the specified part of the file */

        rsize = BLOCK_SIZE(SEND_FILE,num);

        /* read it into the data area of the packet */

        bseek(&PRIVATE.send_fd, num-1);
        bread(&PRIVATE.send_fd, PRIVATE.send_pack.data);

        if (PRIVATE.send_fd.berr)
        {
                ESEND(TX_READERR, (int) num);
                return 1;
	}

        /* format the packet headers */

        PRIVATE.send_pack.seq.batch = SEND_FILE.batch;
        PRIVATE.send_pack.seq.block = num;

        send_seq = (PRIVATE.send_pack.seq.block != PRIVATE.prev_block);

        /* perform Dynamic Code Substitution, if requested */

        if (WS.Option.CodeSubstitution)
        {

                /* determine frequency of each code in this block */

                mem_clear(counts,sizeof(counts));
                for (n=0; n<(int)rsize; n++)
                        ++counts[PRIVATE.send_pack.data[n]];

                /* determine amount of overhead from current mapping */

                #define SMAP PRIVATE.send_pack.map

                n = counts[SMAP.xoff_map] +
                    counts[SMAP.xon_map] +
                    counts[SMAP.dle_map] +
                    counts[SMAP.start_map] +
                    counts[SMAP.end_map];

                /* calculate new mapping if needed */

                send_map = (n > sizeof(control_mapping));
                if (send_map || send_seq)
                {
                        /* prevent mapping of guarded character codes */

                        #define BLOCK_MAPPING(code) counts[code] = 0xFFFF
                        BLOCK_MAPPING(XON_CHR);
                        BLOCK_MAPPING(XOFF_CHR);
                        BLOCK_MAPPING(DLE_CHR);
                        BLOCK_MAPPING(START_PACKET_CHR);
                        BLOCK_MAPPING(END_PACKET_CHR);

                        /* map special characters to least frequently used codes */

                        #define FIND_BEST_MAPPING(MM,code)              \
                                SMAP.MM=0x80^code;                      \
                                   for (n=0; n<256; ++n)                \
                                        if (counts[n]<counts[SMAP.MM])  \
                                                SMAP.MM=n;              \
                                counts[SMAP.MM]=0xFFFF;

                        FIND_BEST_MAPPING(dle_map,   DLE_CHR);
                        FIND_BEST_MAPPING(start_map, START_PACKET_CHR);
                        FIND_BEST_MAPPING(end_map,   END_PACKET_CHR);
                        FIND_BEST_MAPPING(xon_map,   XON_CHR);
                        FIND_BEST_MAPPING(xoff_map,  XOFF_CHR);
                }
        }
        else {
                /* dynamic code substitution is disabled */

                SMAP.xoff_map  = 0x40 ^ XOFF_CHR;
                SMAP.xon_map   = 0x40 ^ XON_CHR;
                SMAP.dle_map   = 0x40 ^ DLE_CHR;
                SMAP.start_map = 0x40 ^ START_PACKET_CHR;
                SMAP.end_map   = 0x40 ^ END_PACKET_CHR;
                send_map = 0;
        }

        /* install any active mapping */

        for (s=PRIVATE.send_pack.data,n=0; n<(int)rsize; ++n,++s)
        {
                if (*s == XOFF_CHR)              *s = SMAP.xoff_map;
                else if (*s == XON_CHR)          *s = SMAP.xon_map;
                else if (*s == DLE_CHR)          *s = SMAP.dle_map;
                else if (*s == START_PACKET_CHR) *s = SMAP.start_map;
                else if (*s == END_PACKET_CHR)   *s = SMAP.end_map;
                else if (*s == SMAP.xoff_map)    *s = XOFF_CHR;
                else if (*s == SMAP.xon_map)     *s = XON_CHR;
                else if (*s == SMAP.dle_map)     *s = DLE_CHR;
                else if (*s == SMAP.start_map)   *s = START_PACKET_CHR;
                else if (*s == SMAP.end_map)     *s = END_PACKET_CHR;
        }

#ifdef DEBUG
        if (WS.Option.Debug)
                printf("<sending %s%sDATA block %u>",
                        send_seq?"SEQ+":"",
                        send_map?"MAP+":"",
                        num);
#endif

        if (num == 1)
                WS.tx_start = bios_clock();

        /* enque the packet for transmission */

        if (send_seq || !WS.Option.MinimalBlocks)
        {
                transmit_message(PACK_DATA_BLOCK_SMD,(uchar *)&PRIVATE.send_pack,
                                        sizeof(sequence_packet)+
                                        sizeof(control_mapping)+ rsize);
        }
        else if (send_map)
        {
                transmit_message(PACK_DATA_BLOCK_MD,(uchar *)&PRIVATE.send_pack.map,
                                        sizeof(control_mapping)+ rsize);
        }
        else
                transmit_message(PACK_DATA_BLOCK_D,(uchar *)PRIVATE.send_pack.data,rsize);

        PRIVATE.prev_block = PRIVATE.send_pack.seq.block+1;
        return 0;
}


/* -------------------------------------------------------------------- */

/*
 * send a block of verification CRC values
 * returns non-0 when no more verification blocks are needed
 *
 */

int pascal send_verify_block(block_number start)
{
        resume_verify_packet pack;
        int i;
        int count;

        if (start > SEND_FILE.blocks)
                return 1;

        count = SEND_FILE.blocks-start+1;
        if (count > MAX_VERIFY_COUNT)
                count = MAX_VERIFY_COUNT;

        PSEND((count > 1)?
                TX_VERMULT:TX_VERSINGLE,
                        (int)start,
                        (int)start+count-1);

        mem_clear(&pack,sizeof(pack));
        pack.base_block = start;
        pack.count = 0;

        bseek(&PRIVATE.send_fd,start-1);
        for (i=0; i<count; i++)
        {
                if ((i&7) == 7)
                        disp_message(".");

                bread(&PRIVATE.send_fd,PRIVATE.send_pack.data);
                if (PRIVATE.send_fd.berr)
                        break;

                pack.check[i] = calculate_CRC(PRIVATE.send_pack.data,SEND_FILE.BlockSize);
                ++pack.count;
        }

        disp_message("\r");

        transmit_message(PACK_VERIFY_BLOCK, (uchar *)&pack,
                sizeof(pack)-((MAX_VERIFY_COUNT-pack.count)*sizeof(CRC_type)));

        /* ComFlush(0); */  /* do not disable handshake */

        return (pack.count < MAX_VERIFY_COUNT);
}


/* -------------------------------------------------------------------- */

/*
 * transmit a single character with a DLE prefix
 *
 */
static void pascal send_dle_char(uchar c)
{
        PRE_WRITE(DLE_CHR);
        if (WS.Option.AlternateDle)
                c ^= 0x40;
        else
                c ^= 0x80;
        PRE_WRITE(c);
}


/* -------------------------------------------------------------------- */

/*
 * transmit each byte in a block, escape special-looking data
 * characters with DLE, otherwise send unchanged
 */

static void pascal send_dle_block(uchar *data,
                                  int size)
{
        register uchar c;
        register uchar pc;

        // use quickest escapes if possible
        if (WS.Option.MinimalBlocks &&
            !WS.Option.XonHandshake &&
            REMOTE_READY.final_ready)
        {
              pc = 0;
              while (size)
              {
                      --size;
                      c = *data++;

                      switch (c)
                      {
                      case START_PACKET_CHR:
                      case END_PACKET_CHR:
                      case DLE_CHR:
                              send_dle_char(c);
                              break;

                      case CAN_CHR:   /* check for two consecutive CAN codes */
                              if (pc == c)
                                      send_dle_char(c);
                              else
                                      PRE_WRITE(c);
                              break;

                      default:
                              PRE_WRITE(c);
                              break;
                      }
                      pc = c;
              }
              return;
        }

        // use more conservative escapes if xon/xoff is active,
        // if minimal blocks is disabled, and always if final ready
        // status has not been negotiated.
        pc = 0;
        while (size)
        {
                --size;
                c = *data++;

                switch (c)
                {
                case XON_CHR+0x80:
                case XOFF_CHR+0x80:
                        if (WS.Option.AlternateDle)
                                send_dle_char(c);
                        else
                                PRE_WRITE(c);
                        break;

                case XON_CHR:
                case XOFF_CHR:
                case START_PACKET_CHR:
                case END_PACKET_CHR:
                case DLE_CHR:
                        send_dle_char(c);
                        break;


                case CAN_CHR:   /* check for two consecutive CAN codes */
                        if (pc == c)
                                send_dle_char(c);
                        else
                                PRE_WRITE(c);
                        break;

                case '@'+0x80:
                case '@':
                        if ((pc & 0x7f) == '\r')
                                send_dle_char(c);
                        else
                                PRE_WRITE(c);
                        break;

                case '\r'+0x80:
                case '\r':
                        if ((pc & 0x7f) == '@')
                                send_dle_char(c);
                        else
                                PRE_WRITE(c);
                        break;

                default:
                        PRE_WRITE(c);
                        break;
                }
                pc = c;
        }
}

/* -------------------------------------------------------------------- */

/*
 * transmit the specified message to the remote (enque data, do not wait)
 *
 * All message frames have the same format:
 *      START_PACKET_CHR
 *      message_type
 *      crc(1..CrcSize)        - only if data_size > 0
 *      data(1)                 - only if data_size > 0
 *      ...                     - only if data_size > 0
 *      data(data_size)         - only if data_size > 0
 *      END_PACKET_CHR
 *
 */

void pascal transmit_message(enum message_types message_type,
                       uchar *data,
                       int data_size)
{
        CRC_type lCRC;

        /* quit right away if carrier is not present */

        if (ComCarrierLost())
                return;

        /* terminate any previous packets in case of flow control failure */
        if (WS.transmit_errors)
        {
                if ((message_type != PACK_READY) &&
                    (message_type != PACK_READY_RECV))
                        PRE_WRITE(END_PACKET_CHR);
        }

        /* transmit the message start and packet type codes */

        PRE_WRITE(START_PACKET_CHR);
        PRE_WRITE(message_type);

        /* transmit the block CRC and the block data */

        if (data_size)
        {
                lCRC = calculate_CRC(data,data_size);

                send_dle_block((uchar *)&lCRC,WS.Option.CrcSize);

#ifdef DEBUG
                if (WS.Option.Debug)
                {
                        printf("\nTRANSMIT BLOCK; type=%c size=%d buf=%04x contents=",
                                        message_type,data_size,data);
                        if (WS.Option.Debug>1)
                        {
                                DUMP_BLOCK(data,data_size);
                        }
                }
#endif

                send_dle_block(data,data_size);

        }

        PRE_WRITE(END_PACKET_CHR);
        PRE_WRITE_FLUSH;
}

cyberbobjr-ultima4-ts-src-game-combat-ts.text:
// Tactical combat on 11x11 maps (*.CON files and dungeon rooms).
// Ported from AVATAR.EXE (EXEPACK-unpacked): main loop 1000:5A6B, player attack 1000:61D1/6012,
// monster damage 1000:5DAB, monster turn 1000:9F7B/9CBC, combat end 1000:837A.
import type { CombatMap } from "../formats/maps";
import type { PlayerRecord } from "../formats/save";
import { ARMOURS, COMBAT_RULES, MONSTERS, NON_EVIL_TILES, PERSON_COMBAT, WALKABLE_TILES, WEAPONS, type MonsterDef, type MonsterRanged } from "../data/tables";
import type { Game } from "./game";
import { useContext } from "./items";
import { CLASS_TILES, T, animFrame } from "./tiles";
import { DIR_NAMES, DIRS, type Dir } from "./maps";

export interface CombatRequest {
  /** Arena: a decoded *.CON file or a dungeon room converted to the same shape. */
  arena: CombatMap;
  /** Monsters: tile and starting square. Use `spawnGroup` to build an encounter from one creature. */
  monsters: { tile: number; x: number; y: number }[];
  /** Where the fight happens (affects fleeing, rewards and what is left on the map afterwards). */
  context: "world" | "town" | "dungeon" | "ship";
  /** For dungeon rooms: index of the direction the party came from (0 N, 1 E, 2 S, 3 W). */
  entryDir?: number;
}

export interface CombatResult {
  outcome: "won" | "fled" | "lost";
  /** Square (arena coordinates) of the last monster killed — where the original drops a chest. */
  lastKill?: { x: number; y: number };
  /** True if every monster killed was evil and none was spared (rewards / karma decided by caller). */
  chest: boolean;
}

export const rand8 = () => Math.floor(Math.random() * 256);
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

const WALKABLE = new Set(WALKABLE_TILES);

/** 1000:7C25 */
export function monsterIndex(tile: number): number {
  if (tile < 0x80) return (tile & 0x1f) + 0x24;
  if (tile < 0x90) return (tile & 0x7f) >> 1;
  return ((tile & 0x7f) >> 2) + 4;
}

export interface CreatureInfo { name: string; baseHp: number; xp: number; maxDamageRoll: number; ranged: MonsterRanged | null; def: MonsterDef | null; }

export function creatureInfo(tile: number): CreatureInfo {
  const i = monsterIndex(tile);
  if (i < MONSTERS.length) {
    const m = MONSTERS[i];
    return { name: m.name, baseHp: m.baseHp, xp: m.xp, maxDamageRoll: m.maxDamageRoll, ranged: m.ranged, def: m };
  }
  const p = PERSON_COMBAT.find((q) => q.tile === (tile & ~1)) ?? PERSON_COMBAT[9];
  return { name: p.name, baseHp: p.baseHp, xp: p.xp, maxDamageRoll: p.baseHp >> 2, ranged: p.ranged, def: null };
}

const has = (c: CreatureInfo, f: MonsterDef["flags"][number]) => c.def?.flags.includes(f) ?? false;
export const isNonEvil = (tile: number) => tile < 0x80 || NON_EVIL_TILES.includes(tile & ~3);
export const isUndead = (tile: number) => [0x9c, 0xbc, 0xc4, 0xe4].includes(tile & ~3);

/** 1000:7E7E: group size and leader promotion for an encounter with `tile`. */
export function spawnGroup(tile: number, arena: CombatMap, partySize: number): CombatRequest["monsters"] {
  let n = 1 + (rand8() & 7);
  while (((n - 1) >> 1) >= partySize) n = 1 + (rand8() % (2 * partySize));
  if (tile < 0x90 || has(creatureInfo(tile), "stationary")) n = 1; // ships, sea monsters and mimics/reapers come alone // UNVERIFIED
  const out: CombatRequest["monsters"] = [];
  for (let i = 0; i < n; i++) {
    let t = tile;
    if (i < n - 1 && tile >= 0x90) {
      const leader = (x: number) => MONSTERS[monsterIndex(x)]?.leaderTile ?? x;
      if (rand8() % 32 === 0) t = leader(leader(tile));
      else if (rand8() % 8 === 0) t = leader(tile);
    }
    const [x, y] = arena.monsterPos[i];
    out.push({ tile: t, x, y });
  }
  return out;
}

interface Monster {
  tile: number; x: number; y: number; hp: number; info: CreatureInfo;
  asleep: boolean; alive: boolean;
}

interface Member { p: PlayerRecord; i: number; x: number; y: number; present: boolean; }

class Combat {
  tiles: Uint8Array;
  monsters: Monster[];
  party: Member[];
  effect: { x: number; y: number; tile: number } | null = null;
  lastKill: { x: number; y: number } | undefined;
  private active = -1;

  constructor(readonly g: Game, readonly req: CombatRequest) {
    this.tiles = req.arena.tiles.slice();
    this.monsters = req.monsters.map((m) => {
      const info = creatureInfo(m.tile);
      // spawn HP = (baseHp>>1) | (rand8 % baseHp)
      const hp = (info.baseHp >> 1) | (rand8() % Math.max(1, info.baseHp));
      return { tile: m.tile, x: m.x, y: m.y, hp, info, asleep: false, alive: true };
    });
    this.party = g.members.map((p, i) => {
      const [x, y] = req.arena.partyPos[i];
      return { p, i, x, y, present: p.status !== "D" };
    });
  }

  tileAt(x: number, y: number) { return x < 0 || y < 0 || x > 10 || y > 10 ? -1 : this.tiles[y * 11 + x]; }
  monsterAt(x: number, y: number) { return this.monsters.find((m) => m.alive && m.x === x && m.y === y); }
  memberAt(x: number, y: number) { return this.party.find((m) => m.present && m.x === x && m.y === y); }
  occupied(x: number, y: number) { return !!this.monsterAt(x, y) || !!this.memberAt(x, y); }

  view = (): number[] => {
    const out = new Array<number>(121);
    const frame = Math.floor(performance.now() / 250);
    for (let i = 0; i < 121; i++) out[i] = this.tiles[i];
    for (const m of this.monsters) if (m.alive) out[m.y * 11 + m.x] = has(m.info, "mimic") && !this.mimicRevealed(m) ? T.CHEST : animFrame(m.tile, frame + m.x);
    for (const m of this.party) {
      if (!m.present) continue;
      // sleepers are shown lying down
      out[m.y * 11 + m.x] = m.p.status === "S" ? T.CORPSE : CLASS_TILES[m.p.klass] + (frame & 1);
    }
    if (this.effect) out[this.effect.y * 11 + this.effect.x] = this.effect.tile;
    return out;
  };

  mimicRevealed(m: Monster) {
    return this.party.some((p) => p.present && Math.abs(p.x - m.x) + Math.abs(p.y - m.y) < 5);
  }

  async flash(x: number, y: number, tile: number = T.HIT_FLASH) {
    this.effect = { x, y, tile };
    await sleep(140);
    this.effect = null;
  }

  /** Animates a projectile from (x,y) along d; returns the first creature square hit or null. */
  async shoot(x: number, y: number, d: Dir, range: number, tile: number, hitsParty: boolean): Promise<{ x: number; y: number } | null> {
    const [dx, dy] = DIRS[d];
    for (let k = 1; k <= range; k++) {
      const cx = x + dx * k, cy = y + dy * k;
      const t = this.tileAt(cx, cy);
      if (t < 0) break;
      if (hitsParty ? this.memberAt(cx, cy) : this.monsterAt(cx, cy)) return { x: cx, y: cy };
      if (!WALKABLE.has(t) && t > T.SHALLOWS) break;
      this.effect = { x: cx, y: cy, tile };
      await sleep(45);
    }
    this.effect = null;
    return null;
  }

  // ------------------------------------------------------------ outcome

  get monstersLeft() { return this.monsters.some((m) => m.alive); }
  get partyLeft() { return this.party.some((m) => m.present && m.p.status !== "D"); }

  // ------------------------------------------------------------ player side

  async run(): Promise<CombatResult> {
    const g = this.g;
    g.viewOverride = this.view;
    try {
      for (;;) {
        for (const m of this.party) {
          if (!this.monstersLeft || !this.partyLeft) break;
          if (!m.present || m.p.status === "D") continue;
          if (m.p.status === "S") continue;
          this.active = m.i; g.activeMember = m.i;
          let again = true;
          while (again) {
            again = false;
            await this.playerTurn(m);
            if (this.g.spellEffect === "Q" && m.present && this.monstersLeft && rand8() & 1) again = true;
          }
          this.active = -1; g.activeMember = -1;
        }
        if (!this.monstersLeft || !this.partyLeft) break;
        await this.monstersTurn();
        g.tickEffects();
        if (!this.partyLeft) break;
      }
    } finally {
      g.viewOverride = null;
    }
    return this.finish();
  }

  private async playerTurn(m: Member) {
    const g = this.g;
    g.con.print(`${m.p.name} with ${WEAPONS[m.p.weapon].name}:\n`);
    for (;;) {
      const k = await g.input.next(15000);
      if (!k) { g.con.println("Pass"); return; }
      const key = k.key;
      const dir = (({ ArrowUp: "N", ArrowDown: "S", ArrowLeft: "W", ArrowRight: "E" }) as Record<string, Dir>)[key];
      if (dir) { await this.moveMember(m, dir); return; }
      switch (key.toLowerCase()) {
        case " ": g.con.println("Pass"); return;
        case "a": await this.attack(m); return;
        case "c":
          g.con.print("Cast Spell! ");
          if (g.castInCombat) await g.castInCombat(this.api(m)); else g.con.println("\nNot Here!");
          return;
        case "r": await g.readyWeapon(m.i); return;
        case "u": {
          if (!g.useItem) { g.con.println("Not Here!"); return; }
          // context for stones at altar rooms and the skull (items.ts)
          const arena = this.req.arena as CombatMap & { altar?: number };
          useContext.pos = { x: m.x, y: m.y };
          useContext.altar = arena.altar ?? -1;
          useContext.room = this.req.context === "dungeon" && "altar" in arena;
          useContext.killAll = () => { for (const x of this.monsters) if (x.tile !== T.LORD_BRITISH) x.alive = false; };
          try { await g.useItem(); } finally { useContext.pos = null; useContext.altar = -1; useContext.room = false; useContext.killAll = null; }
          return;
        }
        case "z": await g.ztatsFor(m.i); continue;
        default: g.con.println("Bad command!"); continue;
      }
    }
  }

  private async moveMember(m: Member, d: Dir) {
    const g = this.g;
    g.con.println(DIR_NAMES[d]);
    const [dx, dy] = DIRS[d];
    const nx = m.x + dx, ny = m.y + dy;
    if (nx < 0 || ny < 0 || nx > 10 || ny > 10) {
      // leaving the arena = fleeing (1000:7962): full-HP members fleeing evil foes cost Valor and Sacrifice.
      // In dungeon rooms the edge taken is the way out (orientation 0 W, 1 N, 2 E, 3 S).
      const arena = this.req.arena as CombatMap & { exitDir?: number | null };
      if ("exitDir" in arena) arena.exitDir = { W: 0, N: 1, E: 2, S: 3 }[d];
      if (!this.monstersLeft) { m.present = false; return; }
      g.con.println("Fleeing!");
      if (m.p.hp === m.p.hpMax && this.monsters.some((x) => x.alive && !isNonEvil(x.tile))) {
        g.karmaDec(2, 2); g.karmaDec(4, 2);
      }
      m.present = false;
      return;
    }
    const t = this.tileAt(nx, ny);
    if (!WALKABLE.has(t) || this.occupied(nx, ny)) { g.con.println("Blocked!"); return; }
    if (t === T.FIRE_FIELD && rand8() & 1) { g.con.println("Slow progress!"); return; }
    m.x = nx; m.y = ny;
    this.terrainEffect(m);
  }

  private terrainEffect(m: Member) {
    const t = this.tileAt(m.x, m.y);
    if ((t === T.POISON_FIELD || t === T.SWAMP) && m.p.status === "G") { m.p.status = "P"; this.g.con.println("Poisoned!"); }
    else if (t === T.FIRE_FIELD || t === T.LAVA) { this.g.damagePlayer(m.p, 16 + (rand8() % 32)); this.g.con.println("Burned!"); }
    else if (t === T.SLEEP_FIELD && m.p.status === "G") { m.p.status = "S"; this.g.con.println("Slept!"); }
  }

  private async attack(m: Member) {
    const g = this.g;
    g.con.print("Attack ");
    const d = await g.askDir("Dir: ");
    if (!d) return;
    const w = m.p.weapon;
    const weapon = WEAPONS[w];
    const [dx, dy] = DIRS[d];
    // Halberd reaches 2 squares (1000:61D1)
    if (w === 10) {
      for (let k = 1; k <= 2; k++) {
        const t = this.monsterAt(m.x + dx * k, m.y + dy * k);
        if (t) { await this.resolveHit(m, t); return; }
      }
      g.con.println("Missed!");
      return;
    }
    const adj = this.monsterAt(m.x + dx, m.y + dy);
    if (!weapon.ranged && !(w === 2 && !adj)) {
      if (!adj) { g.con.println("Missed!"); return; }
      await this.resolveHit(m, adj);
      return;
    }
    // ranged weapons; a dagger with no adjacent target is thrown and lost; flaming oil asks for a range
    let range: number = COMBAT_RULES.rangedWeaponRange;
    if (w === 2 || w === 9) {
      if (g.save.weapons[w] <= 0 && w === 9) { g.con.println("None left!"); return; }
      if (w === 9) {
        g.con.print("Range: ");
        const r = parseInt(await g.getKey(), 10);
        if (!(r >= 0 && r <= 9)) { g.con.println(""); return; }
        g.con.println(String(r));
        range = r;
      }
      if (g.save.weapons[w] > 0) g.save.weapons[w]--;
      if (g.save.weapons[w] === 0) { m.p.weapon = 0; g.con.println("Last one!"); }
    }
    const projectile = w === 14 ? T.MAGIC_FLASH : T.MISSILE;
    const hit = await this.shoot(m.x, m.y, d, range, projectile, false);
    if (w === 9) {
      const fx = hit ? hit.x : m.x + dx * range, fy = hit ? hit.y : m.y + dy * range;
      if (this.tileAt(fx, fy) >= 0) this.tiles[fy * 11 + fx] = T.FIRE_FIELD;
    }
    const target = hit && this.monsterAt(hit.x, hit.y);
    if (!target) { g.con.println("Missed!"); return; }
    await this.resolveHit(m, target);
  }

  /** 1000:6012 hit roll and damage; 1000:5DAB damage to monster. */
  private async resolveHit(m: Member, target: Monster) {
    const g = this.g;
    const w = m.p.weapon;
    const inAbyss = g.save.location === 24;
    const hit = !(inAbyss && w <= 10) && (m.p.dex >= 40 || rand8() <= m.p.dex + 128);
