      if (has(mon.info, "teleports") && rand8() % 8 === 0) {
        for (let k = 0; k < 20; k++) {
          const x = rand8() % 11, y = rand8() % 11;
          if (WALKABLE.has(this.tileAt(x, y)) && !this.occupied(x, y)) { mon.x = x; mon.y = y; break; }
        }
