            if (!break_component(u,start,7,rng)) break;
            --hits;
        } else if (loc == 31) {
            roll = btp_combat_die(rng);
            if (roll == 1 || roll == 6) { if (!u->record[120]) continue; u->record[120] = 255; --hits; }
            if (roll == 2 || roll == 5) { if (u->record[119] >= 2) continue; ++u->record[119]; --hits; }
            if (roll == 3) { u->record[31] = 0; return 1; }
            if (roll == 4) hits -= break_component(u,85,1,rng);
        } else if (loc == 32) {
            if (btp_combat_die(rng) <= 3) {
                unsigned index = btp_combat_die(rng) <= 3 ? 118u : 117u;
                ++u->record[index]; --hits;
                if (u->record[index] >= (index == 118 ? 2u : 3u)) { u->record[32] = 0; return 1; }
            } else hits -= break_component(u,83,2,rng);
        } else {
            unsigned right = loc >= 33, arm = loc == 28 || loc == 33;
            unsigned actuator = right ? 37u : 36u, mask = arm ? 240u : 15u;
            unsigned start = arm ? (right ? 65u : 51u) : (right ? 81u : 79u), count = arm ? 7u : 2u;
            if (!(u->record[actuator]&mask) && !working(u,start,count)) break;
            roll = btp_combat_die(rng);
            if (roll >= 3 && (u->record[actuator]&mask)) {
                unsigned bit = (8u>>(roll-3)) << (arm ? 4 : 0);
                if (!(u->record[actuator]&bit)) continue;
                u->record[actuator] &= (uint8_t)~bit; --hits;
            } else hits -= break_component(u,start,count,rng);
        }
    }
    return 0;
}
static void apply_damage(BtpCombatUnit *u, const BtpCombatData *d, unsigned loc, unsigned damage,
    uint8_t rng[3], BtpShot *shot)
{
    if (btp_vehicle_kind(u->record)) {
        unsigned armor=u->record[loc],taken=armor<damage ? armor : damage;
        u->record[loc]=(uint8_t)(armor-taken);damage-=taken;
        if (damage) {
            unsigned structure=loc+11u;armor=u->record[structure];taken=armor<damage ? armor : damage;
            u->record[structure]=(uint8_t)(armor-taken);++shot->criticals;
            /* Explicit simplified vehicle model: a penetrated region can
               damage the motive system or one weapon in that region. Any
               exhausted hull/turret structure destroys the vehicle. */
            if (!u->record[structure]) shot->destroyed=1;
            else if (btp_combat_die(rng)<=2 && u->record[118]<2) ++u->record[118];
            else if (d->definitions && u->record[123]<d->definitions->mech_count) {
                const BtpMechDefinition *model=&d->definitions->mechs[u->record[123]];
                for (unsigned i=0;i<model->count;++i) if (d->definitions->mount_location[u->record[123]][i]==loc-17 && u->record[51+i]<128) { u->record[51+i]|=128;break; }
            }
        }
        return;
    }
    static const uint8_t overflow[11] = {29,32,34,18,21,18,255,255,23,21,23};
    while (damage && !shot->destroyed) {
        unsigned available = u->record[loc], taken = available < damage ? available : damage;
        u->record[loc] = (uint8_t)(available-taken); damage -= taken;
        if (available && !u->record[loc] && (loc == 28 || loc == 33)) shot->toppled = 1;
        if (loc >= 28) {
            /* 0E31:11AB prints one Critical! for each structural region
               reached, including a region reduced to zero by this shot. */
            ++shot->criticals;
            if (btp_combat_critical(u,d,loc,rng)) shot->destroyed = 1;
        }
        if ((loc == 31 || loc == 32) && !u->record[loc]) shot->destroyed = 1;
        if (!damage || shot->destroyed) break;
        loc = loc <= 24 ? loc+11 : overflow[loc-25];
        if (loc == 255) shot->destroyed = 1;
    }
}
int btp_combat_can_kick(const BtpCombatUnit *u)
{
    return !u->infantry && !btp_vehicle_kind(u->record) && u->record[0] != 255 && (u->record[36]&8u) && (u->record[37]&8u);
}
BtpAttackQuery btp_combat_query(const BtpCombatUnit *a,const BtpCombatUnit *t,
    const BtpCombatData *d,const BtpCombatProfile *profile,unsigned index,int movement,
    unsigned steps,unsigned skill,unsigned unit_id,const uint8_t *explored)
{
    BtpAttackQuery q={.band=3};int kick=!a->infantry && index==11;
    unsigned w=kick ? 32u : btp_combat_weapon(a,index);
    if ((kick && !btp_combat_can_kick(a)) || w>=33 || a->heat>=30) return q;
    BtpWeaponDefinition weapon=btp_unit_weapon_definition(d,a,index);
    unsigned range=btp_combat_mount_range(d,profile,a,t,index,&q.minimum);q.band=range;
    if (range>=3) return q;
    static const uint8_t movement_penalty[13] = {0,0,0,1,1,2,2,3,3,3,4,4,4};
    if (a->infantry) skill=a->record[4+weapon.skill];
    int needed = (kick ? 3 : (int)(2*range+4)) + movement+1 + movement_penalty[steps > 12 ? 12 : steps] - (int)skill;
    if (kick) {
        /* 12E8:02C3 passes the raw enemy ID to 0E31:1B44. For IDs 12..15
           C724+125*id+36/37 lands inside CB0C's explored-map bytes. Preserve
           that original bug: its penalty varies with exploration history,
           rather than always assuming six absent actuators. */
        for (unsigned leg=36;leg<=37;++leg) {
            unsigned bits=unit_id>=12 && unit_id<16 ? explored ? explored[125u*unit_id-1000u+leg] : 0u : a->record[leg];
            for (unsigned mask=1;mask<=4;mask<<=1) needed += !(bits&mask);
        }
    }
    if (!a->infantry && a->record[119]) needed += 2;
    if (!a->infantry) needed += (a->heat >= 8)+(a->heat >= 13)+(a->heat >= 17)+(a->heat >= 24);
    needed += (int)(t->cover/(t->infantry ? 2u : 8u));
    needed+=(int)q.minimum;q.needed=needed;q.heat=weapon.heat;q.valid=1;
    /* Enumerate probabilities, not random draws. damage36 estimates raw
       damage before location armour/criticals; it is not a promised outcome. */
    for (unsigned first=1;first<=6;++first) for (unsigned second=1;second<=6;++second) {
        unsigned roll=first+second;q.hit36+=(int)roll>=needed;
        unsigned damage=kick ? a->record[16]/5u : weapon.damage;
        if (t->infantry) {
            damage=weapon.projectiles&128u ? (weapon.damage&15u)+7u*(weapon.damage>>4)/2u : 127u;
            if (t->record[14]) damage/=2;
            damage*=weapon.projectiles&127u;
            if (damage>t->record[15]) damage=t->record[15];
        } else if (weapon.projectiles&128u) damage=0;
        else if (!kick && weapon.projectiles>1) damage*=d->clusters[7u*roll+weapon.projectiles];
        q.damage36+=damage;
    }
    return q;
}
BtpShot btp_combat_attack_profile(BtpCombatUnit *a,BtpCombatUnit *t,const BtpCombatData *d,
    unsigned index,int movement,unsigned steps,unsigned skill,unsigned unit_id,const uint8_t *explored,
    uint8_t rng[3],const BtpCombatProfile *profile)
{
    int kick=!a->infantry && index==11;BtpShot shot={0};
    BtpAttackQuery q=btp_combat_query(a,t,d,profile,index,movement,steps,skill,unit_id,explored);
    if (!q.valid) return shot;
    unsigned w=kick ? 32u : btp_combat_weapon(a,index);
    BtpWeaponDefinition weapon=btp_unit_weapon_definition(d,a,index);
    if (!a->infantry && !kick && a->record[39+index]!=255) --a->record[39+index];
    if (!a->infantry) a->pool=(uint8_t)(a->pool+weapon.heat);
    int needed=q.needed;
    shot.needed = (int16_t)needed;
    if (t->infantry) {
        unsigned damage=127, count=weapon.projectiles;
        if (count&128u) {
            damage=weapon.damage&15u;
            for (unsigned n=weapon.damage>>4;n;--n) damage+=btp_combat_die(rng);
        }
        if (!damage) damage=1;
        count&=127u;
        shot.hit=(uint8_t)((int)btp_combat_dice(rng)>=needed);
        for (unsigned n=0;n<count;++n) {
            if (!shot.hit) break;
            shot.hit=1;
            /* 12E8:0867 halves the caller's damage local itself. Subsequent
               pellets reuse that reduced amount while armour remains. */
            if (t->record[14]) {
                if (t->record[14]>=damage/2) { damage/=2;t->record[14]=(uint8_t)(t->record[14]-damage); }
                else { damage-=t->record[14];t->record[14]=0; }
            }
            unsigned taken=t->record[15]<damage ? t->record[15] : damage;
            t->record[15]=(uint8_t)(t->record[15]-taken);shot.damage=(uint8_t)(shot.damage+taken);
        }
        shot.destroyed=(uint8_t)!t->record[15];return shot;
    }
    unsigned incoming = btp_combat_direction(a->x,a->y,t->x,t->y);
    if (incoming == 255) incoming = 0;
    unsigned arc = d->arcs[7+(int)t->direction-(int)incoming];
    shot.location = d->locations[11*arc+btp_combat_dice(rng)];
    if (btp_vehicle_kind(t->record)) {
        unsigned relative=(btp_combat_direction(t->x,t->y,a->x,a->y)+8u-t->direction)&7u;
        shot.location=(uint8_t)(relative<=1 || relative==7 ? 17 : relative<=3 ? 22 : relative<=5 ? 23 : 18);
        if (t->record[101] && btp_combat_die(rng)==6) shot.location=21;
    }
    unsigned damage = weapon.damage, cluster = weapon.projectiles;
    if (kick) { damage=a->record[16]/5u;if (!btp_vehicle_kind(t->record)) shot.location=d->locations[3+(btp_rng_next(rng)&8u)]; }
    /* Small personal arms consume the location dice but cannot damage a mech. */
    if (cluster&128u) { shot.location=0;return shot; }
    if (cluster > 1) damage *= d->clusters[7*btp_combat_dice(rng)+cluster];
    shot.hit = (uint8_t)((int)btp_combat_dice(rng) >= needed);
    if (shot.hit) {
        shot.damage = (uint8_t)damage;
        if (w==11 && !btp_vehicle_kind(t->record)) t->burning=3;
        else apply_damage(t,d,shot.location,damage,rng,&shot);
    }
    return shot;
}
BtpShot btp_combat_attack_unit(BtpCombatUnit *a,BtpCombatUnit *t,const BtpCombatData *d,
    unsigned index,int movement,unsigned steps,unsigned skill,unsigned unit_id,const uint8_t *explored,uint8_t rng[3])
{
    return btp_combat_attack_profile(a,t,d,index,movement,steps,skill,unit_id,explored,rng,NULL);
}
BtpShot btp_combat_attack(BtpCombatUnit *a, BtpCombatUnit *t, const BtpCombatData *d,
    unsigned index, int movement, unsigned steps, unsigned skill, uint8_t rng[3])
{
    return btp_combat_attack_unit(a,t,d,index,movement,steps,skill,0,NULL,rng);
}
BtpShot btp_combat_shoot(BtpCombatUnit *a, BtpCombatUnit *t, const BtpCombatData *d,
    unsigned index, int movement, unsigned steps, unsigned skill, uint8_t rng[3])
{
    return btp_combat_attack(a,t,d,index,movement,steps,skill,rng);
}

